using System.IO;
using UnityEngine;
using UnityEditor;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            var textures = AssetDatabase.FindAssets("t:Texture2D", new[]{"Assets/Resources/UI/Ugui/JubaozhaiV1"});
            if (textures.Length != 36)
                throw new System.Exception("Expected 36 Jubaozhai sprites; found " + textures.Length);
            foreach (var guid in textures)
            {
                var path = AssetDatabase.GUIDToAssetPath(guid);
                var importer = (TextureImporter)AssetImporter.GetAtPath(path);
                if (importer.textureType != TextureImporterType.Sprite || importer.spriteImportMode != SpriteImportMode.Single || importer.mipmapEnabled || importer.textureCompression != TextureImporterCompression.Uncompressed || AssetDatabase.LoadAssetAtPath<Sprite>(path) == null)
                    throw new System.Exception("Invalid sprite import: " + path);
            }

            File.WriteAllText(Path.Combine(JubaozhaiUiVerification.OutputDirectory, "import-validation.json"), "{\"status\":\"passed\",\"sprites\":36,\"singleSprite\":true,\"mipmaps\":false,\"compression\":\"Uncompressed\",\"mcp\":\"Unity official Relay\"}");
            JubaozhaiUiVerification.RunTests();
            JubaozhaiUiVerification.CaptureAll();
            JubaozhaiUiVerification.BuildPreview();
            result.Log("JUBAO_FINAL_OK|36 sprites|6 model tests|20 native UI screenshots|preview scene and prefab");
        }
    }
}
